require_once __DIR__.'/../includes/verificar_sesion.php';$roles_permitidos=['cliente'];require_once __DIR__.'/../includes/verificar_rol.php';require_once __DIR__.'/../config/conexion.php';$q=$pdo->prepare('SELECT s.*, c.costo_total, c.estado AS estado_cotizacion FROM solicitudes s LEFT JOIN cotizaciones c ON c.id_solicitud=s.id_solicitud WHERE s.id_cliente=? ORDER BY s.fecha_solicitud DESC');$q->execute([$_SESSION['usuario']['id_usuario']]);$solicitudes=$q->fetchAll();$titulo_pagina='Mis solicitudes';$ruta_base='../';require_once __DIR__.'/../includes/encabezado.php';
?><div class="cabecera-panel"><div><span class="etiqueta">SEGUIMIENTO</span><h1>Mis solicitudes</h1><p>Consulta el estado de cada servicio solicitado.</p></div><a class="boton" href="nueva_solicitud.php">+ Nueva solicitud</a></div><section class="tabla-contenedor"><table class="tabla"><thead><tr><th>ID</th><th>Fecha</th><th>Consola</th><th>Problema</th><th>Estado</th><th>Cotización</th><th></th></tr></thead><tbody><?php if(!$solicitudes): ?><tr><td colspan="7" class="vacio">No hay solicitudes registradas.</td></tr><?php else: foreach($solicitudes as $s): ?><tr><td>#<?= $s['id_solicitud'] ?></td><td><?= date('d/m/Y',strtotime($s['fecha_solicitud'])) ?></td><td><?= escapar($s['marca'].' '.$s['modelo']) ?></td><td><?= escapar($s['problema_reportado']) ?></td><td><span class="<?= estado_clase($s['estado']) ?>"><?= escapar($s['estado']) ?></span></td><td><?= $s['costo_total']!==null?'$'.number_format($s['costo_total'],2):'—' ?></td><td><a class="enlace" href="detalle_solicitud.php?id=<?= $s['id_solicitud'] ?>">Ver detalle →</a></td></tr><?php endforeach; endif; ?></tbody></table></section><?php require_once __DIR__.'/../includes/pie.php'; ?>

